use vstd::prelude::*;

verus! {

    // Specification for the greater function
    fn greater(a: Vec<i8>, b: Vec<i8>) -> (result: Vec<bool>)
        requires
            a.len() == b.len(), // The two input arrays must have the same length
        ensures
            result.len() == a.len(), // The output length must equal the input length
            forall|i: nat| 0 <= i < a.len() as nat ==> 
                result[i] == (a[i] as i32 > b[i] as i32) // Each position indicates if a[i] > b[i]
    {
        let mut result: Vec<bool> = Vec::new();
        let len = a.len() as nat;

        let mut idx: nat = 0;
        while idx < len
            invariant
                idx <= len,
                result.len() == idx as usize,
                forall|j: nat| 0 <= j < idx ==> result[j] == (a[j as usize] as i32 > b[j as usize] as i32),
            decreases len - idx,
        {
            // Compare the elements and push the result
            result.push(a[idx as usize] as i32 > b[idx as usize] as i32);
            idx = idx + 1;
        }
        result
    }
}

